# experiments/run/make_pool.R -- build the frozen instance pool of an application config.
# Usage: Rscript experiments/run/make_pool.R experiments/configs/<name>.R [cores] [n_override]
# Instance k is generated by cfg$instance(cfg$seed + k), so the pool is reproducible and
# independent of the number of cores. The pool, in generation order, is also the "live"
# stream of fresh i.i.d. instances. n_override (pilots only) writes <name>_pilot<k>.rds.
args <- commandArgs(trailingOnly = TRUE)
cfg_path <- args[1]; cores <- if (length(args) > 1) as.integer(args[2]) else max(1L, parallel::detectCores() - 1L)
cfg <- source(cfg_path)$value
n <- if (length(args) > 2) as.integer(args[3]) else cfg$pool_n
out <- if (length(args) > 2) sub("\\.rds$", sprintf("_pilot%d.rds", n), cfg$pool_file) else cfg$pool_file
dir.create(dirname(out), showWarnings = FALSE, recursive = TRUE)
t0 <- Sys.time()
rows <- parallel::mclapply(seq_len(n), function(k) {
  r <- cfg$instance(cfg$seed + k); r$instance <- k; r
}, mc.cores = cores, mc.preschedule = TRUE)
bad <- vapply(rows, inherits, logical(1), "try-error")
if (any(bad)) stop(sum(bad), " instance(s) failed; first: ", as.character(rows[[which(bad)[1]]]))
pool <- do.call(rbind, rows)
pool <- pool[, c("instance", setdiff(names(pool), "instance"))]
attr(pool, "provenance") <- list(config_md5 = unname(tools::md5sum(cfg_path)), n = n,
                                 R = R.version.string, host = Sys.info()[["nodename"]],
                                 started = format(t0), finished = format(Sys.time()))
saveRDS(pool, out)
cat(sprintf("%s: %d instances, %d rows in %.1f min -> %s\n", cfg$name, n, nrow(pool),
            as.numeric(difftime(Sys.time(), t0, units = "mins")), out))
